mapper.select:
select c.*, c.create_time loadingTime, c.empty_cars, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', p.business_type 'project.business_type', p.customer_unit AS receipt_unit, s.`id` 'supplier.id', s.`name` 'supplier.name', c.`price` 'supplier.price', c.shipment_status 'shipmentStatus', c.remark 'remark', sp.`price_type` 'supplier.price_type', CASE c.structure_measure_mode WHEN 1 THEN c.total_net_weight ELSE c.actual_weight END mete from mes_building_cargo_list c left join contract_project p on p.id = c.project_id left join mes_building_supplier_price sp on sp.id = c.supplier_price_id left join scm_supplier s on s.id = sp.supplier_id
and c.bool_delete_enum = 0
and c.project_id = #{projectId}
AND (c.project_id in
#{projectId}
or c.project_id is null)
and c.price_type = #{priceType}
and c.supplier_price_id = #{supplierPriceId}
and c.manufacture_type = #{manufactureType}
and c.status & #{status} > 0
and c.serial_number = #{#{serialNumber}}
and s.`name` = #{supplierName}
and c.license_plate = #{licensePlate}
and c.actual_user_name = #{actualUserName}
and c.driver_name = #{driverName}
and c.user_name = #{userName}
and c.receipt_name = #{receiptName}
and c.audit_receipt_name = #{auditReceiptName}
and c.audit_user_name = #{auditUserName}
and c.serial_number like CONCAT('%',#{serialNumber},'%')
and s.`name` like CONCAT('%',#{supplierName},'%')
and c.license_plate like CONCAT('%',#{licensePlate},'%')
and c.actual_user_name like CONCAT('%',#{actualUserName},'%')
and c.driver_name like CONCAT('%',#{driverName},'%')
and c.user_name like CONCAT('%',#{userName},'%')
and c.receipt_name like CONCAT('%',#{receiptName},'%')
and c.audit_receipt_name like CONCAT('%',#{auditReceiptName},'%')
and c.audit_user_name like CONCAT('%',#{auditUserName},'%')
and c.product_type & #{productType} > 0
and c.category = #{category}
and c.delivery_status = #{deliveryStatus}
and c.shipment_status = #{shipmentStatus}
and date(c.status_update_date) >= date(#{statusUpdateStartDate})
and date(c.status_update_date) <= date(#{statusUpdateEndDate})
and date(c.actual_time) <= date(#{actualEndDate})
and date(c.create_time) >= date(#{startDate})
and date(c.create_time) <= date(#{endDate})
and date(c.actual_time) >= date(#{actualStartDate})
and date(c.actual_time) <= date(#{actualEndDate})
and date(c.audit_time) >= date(#{auditStartDate})
and date(c.audit_time) <= date(#{auditEndDate})
and date(c.audit_receipt_time) >= date(#{auditReceiptStartDate})
and date(c.audit_receipt_time) <= date(#{auditReceiptEndDate})
AND c.id IN
#{item}
order by c.create_time DESC

select date_format(audit_time, '%Y-%m-%d') date,count(*) quantity
from mes_building_cargo_list
WHERE bool_delete_enum = 0 and audit_time IS NOT NULL
AND shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}

    and project_id = #{projectId}


    and date_format(audit_time, '%Y-%m') = #{month}

group by date

SELECT p.id AS project_id, p.name as project_name, p.short_name, p.serial_number, sp.supplier_id, ss.`name` AS supplier_name, sum(c.total_price) AS freight FROM mes_building_cargo_list AS c INNER JOIN mes_building_supplier_price AS sp ON sp.id = c.supplier_price_id LEFT JOIN contract_project AS p ON p.id = c.project_id LEFT JOIN scm_supplier AS ss ON sp.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 and c.delivery_status = 1
AND sp.supplier_id = #{supplierId}
AND sp.supplier_id IS NULL
AND p.contract_sign_body_id = #{branchCompanyId}
GROUP BY p.id, p.NAME, sp.supplier_id, ss.`name`

        SELECT IFNULL(sum(c.total_price), 0) AS freight
        FROM mes_building_cargo_list AS c
        INNER JOIN mes_building_supplier_price AS sp ON sp.id = c.supplier_price_id AND c.bool_delete_enum = 0
        WHERE c.bool_delete_enum = 0
        
            AND c.project_id = #{projectId}
        
        
            AND sp.supplier_id = #{supplierId}
        
        
            AND sp.supplier_id IS NULL
        
        
            AND c.create_time >= #{startDate}
        
        
            AND c.create_time <= #{endDate}

SELECT mbcl.`id`, mbcl.license_plate,-- 车牌号 mbcl.serial_number AS serialNumber, -- 车次 mbcl.audit_time, -- 发运时间 b.`id` AS linkId, -- id b.`name`, -- 产品名称 b.`serial_number` AS productNumber, -- 产品编号 b.`quantity` -- 发运数量 FROM mes_building_cargo_list mbcl LEFT JOIN ( SELECT mbclpl.`id`, -- id mbclpl.`cargo_list_id`, ta.`name`, -- 产品名称 ta.`serial_number`, -- 产品编号 mbclpl.`quantity` -- 发运数量 FROM tech_artifact ta INNER JOIN mes_building_cargo_list_product_link mbclpl ON mbclpl.`product_id` = ta.`id` AND mbclpl.`product_type` = #{productType} WHERE ta.`bool_delete_enum` = 0
and ta.`area_id` in
#{areaId}
AND ta.`monomer_id` = #{monomerId}
) b ON b.cargo_list_id = mbcl.`id` WHERE mbcl.`project_id` = #{projectId} AND mbcl.`bool_delete_enum` = 0 AND mbcl.status & #{status} AND mbcl.shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()} AND mbcl.audit_time IS NOT NULL

        SELECT COUNT(*)
        FROM mes_building_cargo_list
        WHERE `status` & 12
	AND bool_delete_enum = 0
	AND shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
	AND date(audit_time)=date(#{dateTime});

SELECT cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.quantity, a.mete, a.grossMete, a.send_quantity, a.send_mete, a.send_grossMete, a.send_mete / a.mete * 100 ratio FROM ( SELECT a.project_id, sum( quantity ) quantity, sum( a.weight ) mete, sum( a.grossWeight ) grossMete, sum( a.send_quantity ) send_quantity, sum( a.send_weight ) send_mete, sum( a.send_grossWeight ) send_grossMete FROM ( SELECT artifact.project_id, artifact.quantity, artifact.quantity * artifact.net_weight weight, artifact.quantity * artifact.gross_weight grossWeight, IFNULL( send.quantity, 0 ) send_quantity, IFNULL( send.quantity * artifact.net_weight, 0 ) send_weight, IFNULL( send.quantity * artifact.gross_weight, 0 ) send_grossWeight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id, sum( quantity ) quantity FROM mes_building_warehouse_record WHERE type = 2 AND product_type = 2 AND warehouse_type in(0,2) AND bool_delete_enum = 0
AND workshop_id = #{workshopId}
AND DATE_FORMAT(create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
AND DATE_FORMAT(create_time, '%Y/%m' ) = DATE_FORMAT(#{dateTime}, '%Y/%m')
GROUP BY product_id ) send ON send.product_id = artifact.id WHERE artifact.bool_delete_enum = 0
AND artifact.project_id in
#{projectId}
AND artifact.production_line_type_enum = #{productionLineTypeEnum}
) a GROUP BY a.project_id ) a LEFT JOIN contract_project cp ON a.project_id = cp.id
and a.quantity = a.send_quantity
and a.quantity > a.send_quantity
and cp.settlement_status = 1
AND (cp.short_name like concat('%',#{projectName},'%') or cp.serial_number like concat('%',#{projectName},'%') or cp.name like concat('%',#{projectName},'%'))
and cp.status = #{projectStatus}
ORDER BY ratio

select cp.id AS 'projectInfo.id', cp.name AS 'projectInfo.name', cp.short_name AS 'projectInfo.shortName', artifact.quantity, artifact.mete, artifact.grossMete, scheduling.schedulingQuantity, scheduling.schedulingMete, scheduling.schedulingGrossMete, inRecord.inBoundQuantity, inRecord.inBoundMete, inRecord.inBoundGrossMete, outRecord.outBoundQuantity, outRecord.outBoundMete, outRecord.outBoundGrossMete, outMounthRecord.outMounthBoundQuantity, outMounthRecord.outMounthBoundMete, outMounthRecord.outMounthBoundGrossMete, pack.packageQuantity, pack.packageMete, pack.packageGrossMete, ifnull(inRecord.inBoundQuantity,0) - ifnull(outRecord.outBoundQuantity,0) AS stockQuantity, ifnull(inRecord.inBoundMete,0) - ifnull(outRecord.outBoundMete,0) AS stockMete , ifnull(inRecord.inBoundGrossMete,0) - ifnull(outRecord.outBoundGrossMete,0) AS stockGrossMete, cargo.trainNumber from contract_project cp LEFT JOIN ( SELECT count(DISTINCT cargo.id ) trainNumber, cargo.project_id from mes_building_cargo_list cargo inner join mes_building_cargo_list_product_link link on link.cargo_list_id = cargo.id and link.bool_delete_enum = 0 inner join mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id and summary.bool_delete_enum = 0 and summary.product_type = 2
AND summary.monomer_id = #{monomerId}
AND summary.area_id = #{areaId}
AND summary.workshop_id = #{workshopId}
and DATE_FORMAT(summary.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
where cargo.bool_delete_enum = 0 and delivery_status = 1 and status in (4,8) and cargo.project_id = #{projectId} ) cargo on cargo.project_id = cp.id LEFT JOIN ( SELECT project_id, sum(quantity) AS quantity , sum(ifnull(quantity,0) * ifnull(net_weight,0)) AS mete, sum(ifnull(quantity,0) * ifnull(gross_weight,0)) AS grossMete FROM tech_artifact WHERE bool_delete_enum = 0
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
and project_id = #{projectId} ) artifact on artifact.project_id = cp.id LEFT JOIN ( SELECT scheduling.project_id, sum(scheduling.quantity) AS schedulingQuantity, sum(ifnull(scheduling.quantity,0) * ifnull(artifact.net_weight,0)) AS schedulingMete, sum(ifnull(scheduling.quantity,0) * ifnull(artifact.gross_weight,0)) AS schedulingGrossMete FROM mes_building_artifact_scheduling scheduling left JOin tech_artifact artifact on artifact.id = scheduling.product_id WHERE scheduling.bool_delete_enum = 0
AND scheduling.monomer_id = #{monomerId}
AND scheduling.area_id = #{areaId}
AND scheduling.workshop_id = #{workshopId}
and DATE_FORMAT(scheduling.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and scheduling.project_id = #{projectId} ) scheduling on scheduling.project_id = cp.id LEFT JOIN ( SELECT t.project_id, CASE cp.bool_required_warehouse WHEN 0 THEN SUM(t.quantity) ELSE SUM(t.warehouse_quantity) END inBoundQuantity, CASE cp.bool_required_warehouse WHEN 0 THEN sum(t.quantity * artifact.net_weight) ELSE SUM(t.warehouse_quantity * artifact.net_weight) END AS inBoundMete, CASE cp.bool_required_warehouse WHEN 0 THEN sum(t.quantity * artifact.gross_weight) ELSE SUM(t.warehouse_quantity * artifact.gross_weight) END AS inBoundGrossMete FROM ( SELECT record.project_id, record.product_id, record.quantity, IFNULL( SUM( wsp.quantity ), 0 ) warehouse_quantity FROM mes_building_warehouse_summary record LEFT JOIN mes_building_warehouse_storage_product AS wsp ON wsp.warehouse_summary_id = record.id AND wsp.bool_delete_enum = 0 WHERE record.type = 1 AND record.product_type = 2 AND record.bool_delete_enum = 0 AND record.warehouse_type IN ( 0, 2 )
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
AND DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
AND record.project_id = #{projectId} GROUP BY record.id ) t INNER JOIN contract_project cp ON cp.id = t.project_id LEFT JOIN tech_artifact artifact ON artifact.id = t.product_id
GROUP BY t.project_id ) inRecord on inRecord.project_id = cp.id
LEFT JOIN ( SELECT record.project_id, sum(ifnull(record.quantity,0)) AS outBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(artifact.net_weight,0)) AS outBoundMete, sum(ifnull(record.quantity,0) * ifnull(artifact.gross_weight,0)) AS outBoundGrossMete FROM mes_building_warehouse_summary record left JOin tech_artifact artifact on artifact.id = record.product_id WHERE record.type = 2 AND record.product_type = 2 and record.bool_delete_enum = 0 AND record.warehouse_type in (0, 2)
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and record.project_id = #{projectId} ) outRecord on outRecord.project_id = cp.id LEFT JOIN ( SELECT record.project_id, sum(record.quantity) AS outMounthBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(artifact.net_weight,0)) AS outMounthBoundMete, sum(ifnull(record.quantity,0) * ifnull(artifact.gross_weight,0)) AS outMounthBoundGrossMete FROM mes_building_warehouse_summary record left JOin tech_artifact artifact on artifact.id = record.product_id WHERE record.type = 2 AND record.product_type = 2 and record.bool_delete_enum = 0 AND record.warehouse_type in (0, 2)
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y%m' ) = DATE_FORMAT(#{dateMounthTime}, '%Y%m') and record.project_id = #{projectId} ) outMounthRecord on outMounthRecord.project_id = cp.id left join ( select packLink.project_id, sum(packLink.quantity) AS packageQuantity, sum(ifnull(packLink.quantity,0) * ifnull(artifact.net_weight,0)) AS packageMete, sum(ifnull(packLink.quantity,0) * ifnull(artifact.gross_weight,0)) AS packageGrossMete from mes_building_package_link packLink
LEFT JOIN tech_artifact artifact on artifact.id = packLink.product_id and artifact.bool_delete_enum = 0 where packLink.bool_delete_enum = 0 and packLink.product_type = 2 and packLink.project_id = #{projectId} and packLink.warehouse_type IN (0, 2)
AND packLink.monomer_id = #{monomerId}
AND packLink.area_id = #{areaId}
AND packLink.workshop_id = #{workshopId}
and DATE_FORMAT(packLink.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
) pack on pack.project_id = cp.id where cp.id = #{projectId}

select a.id AS 'projectInfo.id', a.name AS 'projectInfo.name', a.short_name AS 'projectInfo.shortName', sum(a.quantity) as quantity, sum(a.mete) as mete, sum(a.grossMete) as grossMete, sum(a.inBoundQuantity) as inBoundQuantity, sum(a.inBoundMete) as inBoundMete, sum(a.inBoundGrossMete) as inBoundGrossMete, sum(a.outBoundQuantity) as outBoundQuantity, sum(a.outBoundMete) as outBoundMete, sum(a.outBoundGrossMete) as outBoundGrossMete, sum(a.outMounthBoundQuantity) as outMounthBoundQuantity, sum(a.outMounthBoundMete) as outMounthBoundMete, sum(a.outMounthBoundGrossMete) as outMounthBoundGrossMete, sum(a.stockQuantity) as stockQuantity, sum(a.stockMete) as stockMete, sum(a.stockGrossMete) as stockGrossMete, cargo.trainNumber from (
select cp.id, cp.name, cp.short_name, artifact.quantity, artifact.mete, artifact.grossMete, inRecord.inBoundQuantity, inRecord.inBoundMete, inRecord.inBoundGrossMete, outRecord.outBoundQuantity, outRecord.outBoundMete, outRecord.outBoundGrossMete, outMounthRecord.outMounthBoundQuantity, outMounthRecord.outMounthBoundMete, outMounthRecord.outMounthBoundGrossMete, ifnull(inRecord.inBoundQuantity,0) - ifnull(outRecord.outBoundQuantity,0) AS stockQuantity, ifnull(inRecord.inBoundMete,0) - ifnull(outRecord.outBoundMete,0) AS stockMete, ifnull(inRecord.inBoundGrossMete,0) - ifnull(outRecord.outBoundGrossMete,0) AS stockGrossMete from contract_project cp
LEFT JOIN ( SELECT project_id, sum(quantity) AS quantity , sum(ifnull(quantity,0) * ifnull(net_weight,0)) AS mete, sum(ifnull(quantity,0) * ifnull(gross_weight,0)) AS grossMete FROM
tech_machine_part
tech_assemble
WHERE bool_delete_enum = 0 and bool_send_directly = 1
and relation_type = 2
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
and project_id = #{projectId} ) artifact on artifact.project_id = cp.id
LEFT JOIN ( SELECT record.project_id, sum(record.quantity) AS inBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(artifact.net_weight,0)) AS inBoundMete, sum(ifnull(record.quantity,0) * ifnull(artifact.gross_weight,0)) AS inBoundGrossMete FROM mes_building_warehouse_summary record left JOin
tech_machine_part artifact
tech_assemble artifact
on artifact.id = record.product_id WHERE record.type = 1 and record.product_type = #{productType} and artifact.bool_send_directly = 1 and record.bool_delete_enum = 0
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and record.project_id = #{projectId} ) inRecord on inRecord.project_id = cp.id
LEFT JOIN ( SELECT record.project_id, sum(ifnull(record.quantity,0)) AS outBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(artifact.net_weight,0)) AS outBoundMete, sum(ifnull(record.quantity,0) * ifnull(artifact.gross_weight,0)) AS outBoundGrossMete FROM mes_building_warehouse_summary record left JOin
tech_machine_part artifact
tech_assemble artifact
on artifact.id = record.product_id WHERE record.type = 2 AND record.product_type = #{productType} and artifact.bool_send_directly = 1 and record.bool_delete_enum = 0
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and record.project_id = #{projectId} ) outRecord on outRecord.project_id = cp.id
LEFT JOIN ( SELECT record.project_id, sum(record.quantity) AS outMounthBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(artifact.net_weight,0)) AS outMounthBoundMete, sum(ifnull(record.quantity,0) * ifnull(artifact.gross_weight,0)) AS outMounthBoundGrossMete FROM mes_building_warehouse_summary record left JOin
tech_machine_part artifact
tech_assemble artifact
on artifact.id = record.product_id WHERE record.type = 2 AND record.product_type = #{productType} and artifact.bool_send_directly = 1 and record.bool_delete_enum = 0
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y%m' ) = DATE_FORMAT(#{dateMounthTime}, '%Y%m') and record.project_id = #{projectId} ) outMounthRecord on outMounthRecord.project_id = cp.id left join ( select packLink.project_id, sum(packLink.quantity) AS packageQuantity, sum(ifnull(packLink.quantity,0) * ifnull(mp.net_weight,0)) AS packageMete, sum(ifnull(packLink.quantity,0) * ifnull(mp.gross_weight,0)) AS packageGrossMete from mes_building_package_link packLink left JOIN
tech_machine_part mp
tech_assemble mp
on mp.id = packLink.product_id and mp.bool_delete_enum = 0 where packLink.bool_delete_enum = 0 and packLink.product_type = #{productType} and mp.bool_send_directly = 1 and packLink.project_id = #{projectId}
AND packLink.monomer_id = #{monomerId}
AND packLink.area_id = #{areaId}
AND packLink.workshop_id = #{workshopId}
and DATE_FORMAT(packLink.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
) pack on pack.project_id = cp.id where cp.id = #{projectId}
) a LEFT JOIN ( SELECT count(distinct cargo.id ) trainNumber, cargo.project_id from mes_building_cargo_list cargo inner join mes_building_cargo_list_product_link link on link.cargo_list_id = cargo.id and link.bool_delete_enum = 0 inner join mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id and summary.bool_delete_enum = 0 and summary.product_type in (1,16)
AND summary.monomer_id = #{monomerId}
AND summary.area_id = #{areaId}
AND summary.workshop_id = #{workshopId}
and DATE_FORMAT(summary.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
where cargo.bool_delete_enum = 0 and delivery_status = 1 and status in (4,8) and cargo.project_id = #{projectId} ) cargo on cargo.project_id = a.id group by a.id,a.name,a.short_name,cargo.trainNumber

select cp.id AS 'projectInfo.id', cp.name AS 'projectInfo.name', cp.short_name AS 'projectInfo.shortName', enclosure.quantity, enclosure.totalLength, enclosure.totalArea, scheduling.schedulingQuantity, scheduling.schedulingTotalLength, scheduling.schedulingTotalArea, inRecord.inBoundQuantity, inRecord.inBoundTotalLength, inRecord.inBoundTotalArea, outRecord.outBoundQuantity, outRecord.outBoundTotalLength, outRecord.outBoundTotalArea, outMounthRecord.outMounthBoundQuantity, outMounthRecord.outMounthBoundTotalLength, outMounthRecord.outMounthBoundTotalArea, ifnull(inRecord.inBoundQuantity,0) - ifnull(outRecord.outBoundQuantity,0) AS stockQuantity, ifnull(inRecord.inBoundTotalLength,0) - ifnull(outRecord.outBoundTotalLength,0) AS stockTotalLength , ifnull(inRecord.inBoundTotalArea,0) - ifnull(outRecord.outBoundTotalArea,0) AS stockTotalArea, cargo.trainNumber from contract_project cp LEFT JOIN ( SELECT count(DISTINCT cargo.id ) trainNumber, cargo.project_id from mes_building_cargo_list cargo inner join mes_building_cargo_list_product_link link on link.cargo_list_id = cargo.id and link.bool_delete_enum = 0 inner join mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id and summary.bool_delete_enum = 0 and summary.product_type = 4
AND summary.category = #{category}
AND summary.plan_id = #{enclosurePlanId}
AND summary.workshop_id = #{workshopId}
and DATE_FORMAT(summary.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
where cargo.bool_delete_enum = 0 and delivery_status = 1 and status in (4,8) and cargo.project_id = #{projectId} ) cargo on cargo.project_id = cp.id LEFT JOIN ( SELECT project_id, sum(quantity) AS quantity , sum(ifnull(quantity,0) * ifnull(length,0)) AS totalLength, sum(ifnull(quantity,0) * ifnull(surface_area,0)) AS totalArea FROM tech_enclosure WHERE bool_delete_enum = 0
AND enclosure_plan_id = #{enclosurePlanId}
AND category = #{category}
and project_id = #{projectId} ) enclosure on enclosure.project_id = cp.id LEFT JOIN ( SELECT scheduling.project_id, sum(scheduling.task_quantity) AS schedulingQuantity, sum(ifnull(scheduling.task_quantity,0) * ifnull(enclosure.length,0)) AS schedulingTotalLength, sum(ifnull(scheduling.task_quantity,0) * ifnull(enclosure.surface_area,0)) AS schedulingTotalArea FROM mes_enclosure_task scheduling left JOin tech_enclosure enclosure on enclosure.id = scheduling.product_id WHERE scheduling.bool_delete_enum = 0
AND scheduling.plan_id = #{enclosurePlanId}
AND enclosure.category = #{category}
AND scheduling.workshop_id = #{workshopId}
and DATE_FORMAT(scheduling.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and scheduling.project_id = #{projectId} ) scheduling on scheduling.project_id = cp.id LEFT JOIN ( SELECT record.project_id, sum(record.quantity) AS inBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(enclosure.length,0)) AS inBoundTotalLength, sum(ifnull(record.quantity,0) * ifnull(enclosure.surface_area,0)) AS inBoundTotalArea FROM mes_building_warehouse_record record left JOin tech_enclosure enclosure on enclosure.id = record.product_id WHERE record.type = 1 AND record.product_type = 4 and record.bool_delete_enum = 0
AND record.plan_id = #{enclosurePlanId}
AND enclosure.category = #{category}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and record.project_id = #{projectId} ) inRecord on inRecord.project_id = cp.id LEFT JOIN ( SELECT record.project_id, sum(ifnull(record.quantity,0)) AS outBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(enclosure.length,0)) AS outBoundTotalLength, sum(ifnull(record.quantity,0) * ifnull(enclosure.surface_area,0)) AS outBoundTotalArea FROM mes_building_warehouse_record record left JOin tech_enclosure enclosure on enclosure.id = record.product_id WHERE record.type = 2 AND record.product_type = 4 and record.bool_delete_enum = 0
AND record.plan_id = #{enclosurePlanId}
AND enclosure.category = #{category}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and record.project_id = #{projectId} ) outRecord on outRecord.project_id = cp.id LEFT JOIN ( SELECT record.project_id, sum(record.quantity) AS outMounthBoundQuantity, sum(ifnull(record.quantity,0) * ifnull(enclosure.length,0)) AS outMounthBoundTotalLength, sum(ifnull(record.quantity,0) * ifnull(enclosure.surface_area,0)) AS outMounthBoundTotalArea FROM mes_building_warehouse_record record left JOin tech_enclosure enclosure on enclosure.id = record.product_id WHERE record.type = 2 AND record.product_type = 4 and record.bool_delete_enum = 0
AND record.plan_id = #{enclosurePlanId}
AND enclosure.category = #{category}
AND record.workshop_id = #{workshopId}
and DATE_FORMAT(record.create_time, '%Y%m' ) = DATE_FORMAT(#{dateMounthTime}, '%Y%m') and record.project_id = #{projectId} ) outMounthRecord on outMounthRecord.project_id = cp.id where cp.id = #{projectId}

SELECT IFNULL(sum(a.quantity * b.net_weight ),0) mete FROM mes_building_warehouse_summary a INNER JOIN tech_artifact b ON a.product_id = b.id and b.bool_delete_enum = 0 LEFT JOIN contract_project cp ON a.project_id = cp.id
AND b.project_id in
#{projectId}
WHERE a.product_type = 2 AND a.type =2 and a.bool_delete_enum = 0
AND DATE_FORMAT(a.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
AND a.workshop_id = #{workshopId}
AND cp.status = #{projectStatus}

SELECT IFNULL(sum(a.quantity * b.length ),0) totalLength, IFNULL(sum(a.quantity * b.surface_area ),0) totalArea FROM mes_building_warehouse_record a INNER JOIN tech_enclosure b ON a.product_id = b.id and b.bool_delete_enum = 0 LEFT JOIN contract_project cp ON a.project_id = cp.id
AND b.project_id in
#{projectId}
WHERE a.product_type = 4 AND a.type =2 and a.bool_delete_enum = 0
AND DATE_FORMAT(a.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
AND a.workshop_id = #{workshopId}
AND cp.status = #{projectStatus}

select count(DISTINCT cargo.id) from mes_building_cargo_list_product_link link INNER JOIN mes_building_cargo_list cargo on cargo.id = link.cargo_list_id and (cargo.status = 4 or cargo.status = 8) and cargo.shipment_status != 2 and cargo.bool_delete_enum = 0
and DATE_FORMAT(cargo.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and cargo.project_id =#{projectId}
and date(cargo.create_time) >= date(#{startDate})
and date(cargo.create_time) <= date(#{endDate})
LEFT JOIN mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id and summary.bool_delete_enum = 0 LEFT JOIN contract_project cp ON summary.project_id = cp.id WHERE link.product_type = 2 and link.bool_delete_enum = 0
AND summary.workshop_id = #{workshopId}
AND summary.project_id in
#{projectId}
AND cp.status = #{projectStatus}

select count(DISTINCT cargo.id) from mes_building_cargo_list_product_link link INNER JOIN tech_enclosure b ON link.product_id = b.id
AND b.project_id in
#{projectId}
INNER JOIN mes_building_cargo_list cargo on cargo.id = link.cargo_list_id and (cargo.status = 4 or cargo.status = 8) and cargo.shipment_status != 2
and DATE_FORMAT(cargo.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and cargo.project_id =#{projectId}
and date(cargo.create_time) >= date(#{startDate})
and date(cargo.create_time) <= date(#{endDate})
LEFT JOIN mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id LEFT JOIN contract_project cp ON summary.project_id = cp.id WHERE link.product_type = 4
AND summary.workshop_id = #{workshopId}
AND cp.status = #{projectStatus}

SELECT pm.id monomerId, pm.`name` monomerName, pa.id areaId, pa.`name` areaName, a.workshopName AS workshopName, a.id, a.name, a.serial_number, a.material, a.remark, a.specification, a.length, a.net_weight, a.surface_area, a.total_area, a.gross_weight, a.quantity, a.total_net_weight, a.total_gross_weight, a.inno_quantity inboundQuantity, a.send_quantity cargoQuantity, a.send_gross_weight cargo_gross_weight, a.send_net_weight cargo_net_weight, a.cargoDate FROM ( SELECT a.monomer_id, a.area_id, a.id, a.name, a.serial_number, a.material, a.remark, a.specification, a.length, IFNULL(a.surface_area, 0) / 1000000 AS surface_area, IFNULL(a.surface_area * a.quantity, 0) / 1000000 AS total_area, inno.workshopName, IFNULL(a.net_weight,0) net_weight, IFNULL(a.gross_weight,0) gross_weight, IFNULL(a.quantity,0) quantity, IFNULL(a.net_weight * a.quantity,0) total_net_weight, IFNULL(a.gross_weight * a.quantity,0) total_gross_weight, IFNULL(inno.inno_quantity,0) inno_quantity, IFNULL(send.send_quantity ,0) send_quantity, IFNULL(a.net_weight * send.send_quantity, 0 ) send_net_weight, IFNULL(a.gross_weight * send.send_quantity, 0 ) send_gross_weight, send.cargoDate FROM tech_artifact a LEFT JOIN ( SELECT record.product_id, group_concat(distinct workshop.name) AS workshopName, sum(record.quantity ) inno_quantity FROM mes_building_warehouse_record record LEFT JOIN mes_building_workshop workshop on workshop.id = record.workshop_id WHERE record.bool_delete_enum = 0 AND record.type = 1 AND record.product_type = 2 AND record.warehouse_type in(0,2)
AND record.project_id = #{projectId}
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{shopId}
GROUP BY record.product_id ) inno ON inno.product_id = a.id LEFT JOIN ( SELECT record.product_id, sum( record.quantity ) send_quantity, max( record.create_time ) cargoDate FROM mes_building_warehouse_record record WHERE record.bool_delete_enum = 0 AND record.type = 2 AND record.product_type = 2 AND record.warehouse_type in(0,2)
and date(record.create_time) >= date(#{startDate})
and date(record.create_time) <= date(#{endDate})
AND record.project_id = #{projectId}
AND record.monomer_id = #{monomerId}
AND record.area_id = #{areaId}
AND record.workshop_id = #{shopId}
GROUP BY record.product_id ) send ON send.product_id = inno.product_id WHERE a.bool_delete_enum = 0 and a.bool_all_part_send_directly = 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.production_line_type_enum = #{productionLineTypeEnum}
AND a.serial_number like concat('%',#{serialNumber},'%')
) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id
AND a.cargoDate is not null
order by a.send_quantity

select * from (
SELECT pm.id monomerId, pm.`name` monomerName, pa.id areaId, pa.`name` areaName, workshop.id AS workshopId, workshop.name AS workshopName, a.name, a.serial_number, a.material, a.remark, a.net_weight, a.gross_weight, a.quantity, a.total_net_weight, a.total_gross_weight, a.workshop_id, a.bool_all_part_send_directly, a.inno_quantity inboundQuantity, a.send_quantity cargoQuantity, a.send_gross_weight cargo_gross_weight, a.send_net_weight cargo_net_weight, a.cargoDate FROM ( SELECT a.monomer_id, a.area_id, a.name, a.serial_number, a.material, a.remark, a.bool_all_part_send_directly, inno.workshop_id, IFNULL(a.net_weight,0) net_weight, IFNULL(a.gross_weight,0) gross_weight, IFNULL(a.quantity,0) quantity, IFNULL(a.net_weight * a.quantity,0) total_net_weight, IFNULL(a.gross_weight * a.quantity,0) total_gross_weight, IFNULL(inno.inno_quantity,0) inno_quantity, IFNULL(send.send_quantity ,0) send_quantity, IFNULL(a.net_weight * send.send_quantity, 0 ) send_net_weight, IFNULL(a.gross_weight * send.send_quantity, 0 ) send_gross_weight, send.cargoDate FROM
tech_machine_part a
tech_assemble a
LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity ) inno_quantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND type = 1 AND product_type = #{productType}
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) inno ON inno.product_id = a.id LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity ) send_quantity, max( create_time ) cargoDate FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND type = 2 AND product_type = #{productType}
and date(create_time) >= date(#{startDate})
and date(create_time) <= date(#{endDate})
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) send ON send.product_id = inno.product_id and send.workshop_id = inno.workshop_id WHERE a.bool_delete_enum = 0 and a.bool_send_directly = 1
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.production_line_type_enum = #{productionLineTypeEnum}
AND a.serial_number like concat('%',#{serialNumber},'%')
and a.relation_type = 2
) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN mes_building_workshop workshop on workshop.id = a.workshop_id
AND a.workshop_id = #{workshopId}
AND a.cargoDate is not null
) a order by a.cargoQuantity,a.workshop_id

SELECT plan.id enclosurePlanId, plan.`name` enclosurePlanName, workshop.id AS workshopId, workshop.name AS workshopName, a.name, a.serial_number, a.plate, a.length, a.surface_area, a.remark, a.quantity, a.workshop_id, a.totalLength, a.totalArea, a.inno_quantity inboundQuantity, a.send_quantity cargoQuantity, a.send_total_length cargoTotalLength, a.send_total_area cargoTotalArea FROM ( SELECT a.name, a.enclosure_plan_id, a.serial_number, a.plate, a.length, a.surface_area, a.remark, IFNULL(a.quantity,0) quantity, inno.workshop_id, IFNULL(a.length * a.quantity,0) totalLength, IFNULL(a.surface_area * a.quantity,0) totalArea, IFNULL(inno.inno_quantity,0) inno_quantity, IFNULL(send.send_quantity ,0) send_quantity, IFNULL(a.length * send.send_quantity, 0 ) send_total_length, IFNULL(a.surface_area * send.send_quantity, 0 ) send_total_area FROM tech_enclosure a LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity) inno_quantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND type = 1 AND product_type = 4
AND project_id = #{projectId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) inno ON inno.product_id = a.id LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity ) send_quantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND type = 2 AND product_type = 4
AND project_id = #{projectId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) send ON send.product_id = inno.product_id and send.workshop_id = inno.workshop_id WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.enclosure_plan_id = #{enclosurePlanId}
AND a.category = #{category}
AND a.serial_number like concat('%',#{serialNumber},'%')
) a LEFT JOin enclosure_plan plan on plan.id = a.enclosure_plan_id LEFT JOIN mes_building_workshop workshop on workshop.id = a.workshop_id and workshop.type = 4
AND a.workshop_id = #{workshopId}
order by a.send_quantity DESC,a.workshop_id

SELECT pm.id monomerId, pm.`name` monomerName, pa.id areaId, pa.`name` areaName, a.name, a.serial_number, a.specification, a.measure_unit, a.quantity, ifnull(a.mete,0) mete, a.accounting_unit, a.remark, bool_weight_type_enum, a.send_quantity cargoQuantity, ROUND(a.mete * a.send_quantity / a.quantity, 2) AS cargo_mete, ROUND(a.mete * (ifnull(a.quantity,0) - ifnull(a.send_quantity,0)) / a.quantity , 2) AS un_cargo_mete, ifnull(a.quantity,0) - ifnull(a.send_quantity,0) AS unCargoQuantity FROM ( SELECT a.name, a.project_id, a.monomer_id, a.area_id, a.serial_number, a.specification, a.measure_unit, a.quantity, a.mete, a.accounting_unit, a.remark, bool_weight_type_enum, IFNULL(send.send_quantity ,0) send_quantity FROM tech_standard_part a LEFT JOIN ( SELECT product_id, sum( quantity) send_quantity FROM mes_building_warehouse_record WHERE bool_delete_enum = 0 AND type = 2 AND product_type = 8
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
GROUP BY product_id ) send ON send.product_id = a.id WHERE a.bool_delete_enum = 0 and a.relation_type = #{relationType} and a.use_property = 1
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN contract_project cp ON a.project_id = cp.id where cp.bool_delete_enum = 0
AND cp.status = #{projectStatus}
order by a.send_quantity

SELECT a.id, a.project_id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.id monomerId, pm.`name` monomerName, pa.id areaId, pa.`name` areaName, a.name, a.serial_number, a.specification, a.measure_unit, a.quantity, ifnull(a.mete, 0) mete, a.accounting_unit, a.remark, ROUND(a.mete * IFNULL(sum(rcd.quantity), 0) / a.quantity, 2) AS cargo_mete, ROUND(a.mete * (a.quantity - ifnull(sum(rcd.quantity), 0)) / a.quantity , 2) AS un_cargo_mete, IFNULL(sum(rcd.quantity), 0) cargo_quantity, a.quantity - ifnull(sum(rcd.quantity), 0) AS un_cargo_quantity FROM tech_standard_part a LEFT JOIN mes_building_warehouse_record rcd ON a.id = rcd.product_id AND rcd.bool_delete_enum = 0 AND rcd.type = 2 AND rcd.product_type = 8 LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id WHERE a.bool_delete_enum = 0 and a.use_property = 1
and a.relation_type = #{relationType}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.category = #{category}
AND a.enclosure_plan_id = #{enclosurePlanId}
AND a.serial_number LIKE CONCAT('%', #{serialNumber},'%')
GROUP BY a.id ORDER BY a.id DESC

SELECT COUNT(*) quantity FROM mes_building_cargo_list WHERE status & 12 AND bool_delete_enum=0
AND DATE_FORMAT( audit_time, '%Y')=DATE_FORMAT( #{dateTime}, '%Y')
AND DATE_FORMAT( audit_time, '%Y/%m')=DATE_FORMAT( #{dateTime}, '%Y/%m')
AND shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
AND project_id = #{projectId}
and project_id in
#{item}
and date(actual_time) <= date(#{auditEndDate})
and date(actual_time) >= date(#{auditStartDate})

SELECT sum(cargo.mete) FROM ( SELECT CASE cargo.structure_measure_mode WHEN 1 THEN IFNULL(cargo.total_net_weight,0) ELSE IFNULL(cargo.actual_weight,0) END mete FROM mes_building_cargo_list cargo WHERE cargo.bool_delete_enum = 0 AND cargo.`status` in(4,8) AND cargo.shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
AND DATE_FORMAT( cargo.audit_time, '%Y')=DATE_FORMAT( #{dateTime}, '%Y')
AND DATE_FORMAT( cargo.audit_time, '%Y/%m')=DATE_FORMAT( #{dateTime}, '%Y/%m')
AND cargo.project_id = #{projectId}
and cargo.project_id in
#{item}
and date(cargo.actual_time) <= date(#{auditEndDate})
and date(cargo.actual_time) >= date(#{auditStartDate})
) cargo

select * from (
select project.id AS 'projectInfo.id', project.name AS 'projectInfo.name', project.short_name AS 'projectInfo.shortName', monomer.id AS 'monomer.id', monomer.name AS 'monomer.name', area.id AS 'area.id', area.name AS 'area.name', artifact.id AS productId, artifact.serial_number, artifact.specification, artifact.material, artifact.net_weight, artifact.gross_weight, artifact.bool_all_part_send_directly,
workshop.id AS 'workshop.id', workshop.name AS 'workshop.name', sum(common.quantity) quantity, sum(common.quantity * ifnull(artifact.net_weight,0)) totalNetWeight, sum(common.quantity * ifnull(artifact.gross_weight,0)) totalGrossNetWeight,
artifact.quantity, artifact.total_net_weight, artifact.total_gross_weight AS totalGrossNetWeight,
#{productType} AS productType
,common.workshop_id
from
tech_machine_part artifact
tech_assemble artifact
inner Join mes_building_warehouse_record common on common.product_id = artifact.id and common.type = 1 and common.product_type = #{productType}
inner Join mes_building_warehouse_record common on common.product_id = artifact.id and common.type = 2 and common.product_type = #{productType}
inner Join mes_building_warehouse_record common on common.product_id = artifact.id and common.type = 2 and common.product_type = #{productType} and DATE_FORMAT(common.create_time, '%Y%m' ) = DATE_FORMAT(#{dateMounthTime}, '%Y%m')
inner JOin ( select i.workshop_id, i.product_id, sum(i.quantity) - IFNULL(o.quantity,0) quantity from mes_building_warehouse_record i Left JOin ( select o.workshop_id, o.product_id, sum(o.quantity) quantity from mes_building_warehouse_record o where o.type = 2 and o.bool_delete_enum = 0 and o.project_id = #{projectId} and o.product_type = #{productType} group by o.product_id,o.workshop_id ) o on o.product_id = i.product_id and o.workshop_id = i.workshop_id where i.type = 1 and i.bool_delete_enum = 0 and i.project_id = #{projectId} and i.product_type = #{productType}
AND i.monomer_id = #{monomerId}
AND i.area_id = #{areaId}
and DATE_FORMAT(i.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
group by i.product_id,i.workshop_id ) common on common.product_id = artifact.id and common.quantity > 0
LEFT JOin contract_project project on project.id = artifact.project_id LEFT JOin plan_monomer monomer on monomer.id = artifact.monomer_id LEFT JOin plan_area area on area.id = artifact.area_id
LEFT JOIN mes_building_workshop workshop ON workshop.id = common.workshop_id
where artifact.project_id = #{projectId} and artifact.bool_delete_enum = 0 and artifact.bool_send_directly = 1
and artifact.relation_type = 2
AND artifact.monomer_id = #{monomerId}
AND artifact.area_id = #{areaId}
AND common.workshop_id = #{workshopId}
and DATE_FORMAT(common.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
GROUP BY artifact.id
,common.workshop_id
) a
order by a.workshop_id

select count(DISTINCT a.count) from ( select cargo.id count from mes_building_cargo_list_product_link link INNER JOIN tech_assemble b ON link.product_id = b.id INNER JOIN mes_building_cargo_list cargo on cargo.id = link.cargo_list_id and (cargo.status = 4 or cargo.status = 8) and cargo.shipment_status != 2 LEFT JOIN mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id WHERE link.product_type = 16 and b.bool_send_directly = 1 AND summary.type = 1
AND b.production_line_type_enum = #{productionLineTypeEnum}
AND b.project_id in
#{projectId}
and DATE_FORMAT(cargo.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and cargo.project_id =#{projectId}
and date(cargo.create_time) >= date(#{startDate})
and date(cargo.create_time) <= date(#{endDate})
AND summary.workshop_id = #{workshopId}
union all select cargo.id count from mes_building_cargo_list_product_link link INNER JOIN tech_machine_part b ON link.product_id = b.id INNER JOIN mes_building_cargo_list cargo on cargo.id = link.cargo_list_id and (cargo.status = 4 or cargo.status = 8) and cargo.shipment_status != 2 LEFT JOIN mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id WHERE link.product_type = 1 and b.bool_send_directly = 1 AND summary.type = 1
AND b.production_line_type_enum = #{productionLineTypeEnum}
AND b.project_id in
#{projectId}
and DATE_FORMAT(cargo.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and cargo.project_id =#{projectId}
and date(cargo.create_time) >= date(#{startDate})
and date(cargo.create_time) <= date(#{endDate})
AND summary.workshop_id = #{workshopId}
)a
